<parameter name="content">import { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (props: FallbackProps) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

export interface FallbackProps {
  error: Error;
  errorInfo: ErrorInfo;
  retry: () => void;
}

function DefaultFallback({ error, errorInfo, retry }: FallbackProps) {
  return (
    <div role="alert" style={styles.container}>
      <h2 style={styles.heading}>Something went wrong</h2>
      <p style={styles.message}>{error.message}</p>
      <details style={styles.details}>
        <summary style={styles.summary}>Stack trace</summary>
        <pre style={styles.pre}>
          {error.stack}
          {errorInfo.componentStack}
        </pre>
      </details>
      <button onClick={retry} style={styles.button}>
        Try again
      </button>
    </div>
  );
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, errorInfo: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    this.setState({ errorInfo });

    const { onError } = this.props;
    if (onError) {
      onError(error, errorInfo);
    } else {
      console.error("[ErrorBoundary] Caught render error:", error, errorInfo);
    }
  }

  retry = () => {
    this.setState({ error: null, errorInfo: null });
  };

  render() {
    const { error, errorInfo } = this.state;
    const { children, fallback } = this.props;

    if (error && errorInfo) {
      const fallbackProps: FallbackProps = { error, errorInfo, retry: this.retry };
      return fallback ? fallback(fallbackProps) : <DefaultFallback {...fallbackProps} />;
    }

    return children;
  }
}

const styles: Record<string, React.CSSProperties> = {
